const {
  createSvgComponentLoader,
} = require('../../../native-composition/svg-component-source.cjs');

// Octane follows React host semantics: refs are props and inner markup is
// trusted HTML. Native attribute names and `class` pass through unchanged.
module.exports = createSvgComponentLoader(
  ({ attributes, markup, origin }) => `/** @jsxImportSource octane */
// Generated by UltraModern from ${origin}. Do not edit.
import { trustHTML } from 'octane';

const attributes: { readonly [name: string]: string } = ${attributes};
const markup = trustHTML(${markup});

export default function SvgComponent(props: { readonly [name: string]: unknown }) {
  return <svg {...attributes} {...props} dangerouslySetInnerHTML={markup} />;
}
`,
);
